/** AJV6 escapes these characters when quoting a bracket property name. */
const ESCAPES: Record<string, string> = { n: '\n', r: '\r', t: '\t', f: '\f' };
/** Tokenize AJV6 dot, array-index and quoted-property segments. */
const PATH_SEGMENTS = /\.([^.[\]]+)|\[(?:([0-9]+)|'((?:\\.|[^'\\])*)')\]/g;
/** Decode only the escapes generated by AJV6 single-quoted property names. */
const QUOTED_ESCAPE = /\\([\\'nrtf])/g;
/** Recognize one quoted property without an embedded quote or escape. */
const SINGLE_QUOTED_PATH = /^\['[^'\\]*'\]$/;

/**
 * Escape an opaque property name only when RFC 6901 requires a replacement.
 * @param name - A decoded property name; dots remain literal name characters
 * @returns A JSON Pointer segment with tilde and slash escaped
 */
const escapeName = (name: string): string => {
  if (name.indexOf('~') === -1 && name.indexOf('/') === -1) return name;
  let escaped = '';
  for (let index = 0; index < name.length; index++) {
    const character = name[index];
    escaped += character === '~' ? '~0' : character === '/' ? '~1' : character;
  }
  return escaped;
};

/**
 * Convert AJV6's generated property syntax to an RFC 6901 path.
 * @param path - AJV6 dataPath in dotted/bracket syntax or its jsonPointers output
 * @returns The root empty string or an escaped pointer preserving empty names
 */
export const toJSONPointer = (path: string): string => {
  if (!path || path[0] === '/') return path;
  if (path.indexOf('[') === -1) {
    path = escapeName(path);
    let pointer = '';
    let start = path[0] === '.' ? 1 : 0;
    for (let dot = path.indexOf('.', start); dot !== -1; dot = path.indexOf('.', start)) {
      pointer += '/' + path.slice(start, dot);
      start = dot + 1;
    }
    return pointer + '/' + path.slice(start);
  }
  if (SINGLE_QUOTED_PATH.test(path))
    return '/' + escapeName(path.slice(2, -2));
  if (path[0] !== '.' && path[0] !== '[') path = '.' + path;
  let pointer = '';
  for (const match of path.matchAll(PATH_SEGMENTS)) {
    const name = match[1] ?? match[2] ?? match[3].replace(QUOTED_ESCAPE,
      (_, character: string) => ESCAPES[character] ?? character);
    pointer += '/' + escapeName(name);
  }
  return pointer;
};
